/bin/bash -lc "python3 - <<'PY'
import cv2,numpy as np
im=cv2.imread('first_frame.png'); g=cv2.cvtColor(im,cv2.COLOR_BGR2GRAY)
for meth in ['raw','bilat','clahe','blur']:
 if meth=='raw':a=g
 elif meth=='bilat':a=cv2.bilateralFilter(g,7,40,40)
 elif meth=='clahe':a=cv2.createCLAHE(2,(8,8)).apply(g)
 else:a=cv2.GaussianBlur(g,(5,5),1)
 print('\\n',meth)
 all=[]
 for p1 in [40,60,80,100,130,160]:
  for p2 in [8,10,12,14,16,18,20,22]:
   c=cv2.HoughCircles(a[120:240,170:370],cv2.HOUGH_GRADIENT,dp=1,minDist=10,param1=p1,param2=p2,minRadius=8,maxRadius=19)
   if c is not None:
    for x,y,r in c[0]:all.append((round(x+170),round(y+120),round(r)))
 from collections import Counter
 for c,n in Counter(all).most_common(30): print(n,c)
# gradient circularity score centers/radii: fraction gradients aligned radial around ring
sx=cv2.Sobel(g,cv2.CV_32F,1,0,ksize=3); sy=cv2.Sobel(g,cv2.CV_32F,0,1,ksize=3); mag=np.hypot(sx,sy)
res=[]
for y in range(130,231,2):
 for x in range(180,351,2):
  best=0;br=0
  for r in range(9,19):
   th=np.linspace(0,2*np.pi,72,endpoint=False); xx=np.clip(np.round(x+r*np.cos(th)).astype(int),0,511); yy=np.clip(np.round(y+r*np.sin(th)).astype(int),0,287)
   gm=mag[yy,xx]; dot=np.abs((sx[yy,xx]*np.cos(th)+sy[yy,xx]*np.sin(th))/(gm+1e-3))
   score=np.mean(gm*dot) # radial gradient
   if score>best:best=score;br=r
  res.append((best,x,y,br))
print('\\nscore')
sel=[]
for z in sorted(res,reverse=True):
 if all((z[1]-q[1])**2+(z[2]-q[2])**2>100 for q in sel):sel.append(z)
 if len(sel)>=30:break
for z in sel:print(tuple(round(v,1) if isinstance(v,float) else v for v in z))
PY"
